//! Vendored Frappe constants. Generated by `cargo xtask codegen`; never
//! hand-edited.
//!
//! The server is branch-agnostic, so a value outside a table degrades to
//! "unknown" and reports nothing unless the detected version matches
//! [`SNAPSHOT`] exactly — [31](../../../docs/specs/31-performance.md).
//!
//! ```text
//! source   frappe 17.0.0-dev @ 5a94ce857600ef1fef23774601a0cfd442837735
//! scraped  frappe/public/js/frappe/form/**
//! ```

/// The `frappe` checkout the tables below were taken from.
///
/// [31](../../../docs/specs/31-performance.md)'s version gate compares this
/// against `<frappe package>/__init__.py`'s `__version__`; anything else means
/// an unrecognized value is "unknown", never "invalid".
pub struct Snapshot {
    /// `__version__` as written in the checkout.
    pub version: &'static str,
    /// The commit the tables were generated from.
    pub commit: &'static str,
}

/// The snapshot these tables came from.
pub const SNAPSHOT: Snapshot = Snapshot {
    version: "17.0.0-dev",
    commit: "5a94ce857600ef1fef23774601a0cfd442837735",
};

/// Form lifecycle event names —
/// [11](../../../docs/specs/11-surface-javascript.md).
///
/// Sorted, so membership is a binary search and a codegen diff is a line diff.
pub const FORM_LIFECYCLE_EVENTS: &[&str] = &[
    "after_cancel",
    "after_discard",
    "after_save",
    "after_workflow_action",
    "attachments_change",
    "before_cancel",
    "before_discard",
    "before_load",
    "before_save",
    "before_submit",
    "before_workflow_action",
    "dashboard_update",
    "dirty",
    "form_render",
    "on_submit",
    "on_tab_change",
    "onload",
    "onload_post_render",
    "refresh",
    "rename",
    "render_complete",
    "setup",
    "timeline_refresh",
    "validate",
];

/// Whether `name` is a form lifecycle event in this snapshot.
#[must_use]
pub fn is_form_lifecycle_event(name: &str) -> bool {
    FORM_LIFECYCLE_EVENTS.binary_search(&name).is_ok()
}

/// The per-table event forms of
/// [11](../../../docs/specs/11-surface-javascript.md).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TableEvent {
    /// `<table_fieldname>_add`.
    Add,
    /// `<table_fieldname>_remove`.
    Remove,
    /// `before_<table_fieldname>_remove`.
    BeforeRemove,
}

/// Split a per-table event key into the `Table` fieldname it names and the
/// event.
///
/// The fieldname is returned unchecked: whether the DocType has such a `Table`
/// field is a schema question, and this crate does not hold the schema.
#[must_use]
pub fn table_event(key: &str) -> Option<(&str, TableEvent)> {
    if let Some(rest) = key.strip_prefix("before_")
        && let Some(fieldname) = rest.strip_suffix("_remove")
    {
        return Some((fieldname, TableEvent::BeforeRemove));
    }
    if let Some(fieldname) = key.strip_suffix("_remove") {
        return Some((fieldname, TableEvent::Remove));
    }
    if let Some(fieldname) = key.strip_suffix("_add") {
        return Some((fieldname, TableEvent::Add));
    }
    None
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_table_is_sorted_so_the_binary_search_holds() {
        assert!(
            FORM_LIFECYCLE_EVENTS
                .windows(2)
                .all(|pair| pair[0] < pair[1])
        );
    }

    #[test]
    fn lifecycle_names_are_recognized_and_near_misses_are_not() {
        assert!(is_form_lifecycle_event("onload_post_render"));
        assert!(is_form_lifecycle_event("before_workflow_action"));
        // `stauts` is the typo the `unknown-form-event` check exists for.
        assert!(!is_form_lifecycle_event("stauts"));
        assert!(!is_form_lifecycle_event("status"));
        assert!(!is_form_lifecycle_event("on_hide"));
    }

    #[test]
    fn table_events_split_into_fieldname_and_event() {
        assert_eq!(table_event("items_add"), Some(("items", TableEvent::Add)));
        assert_eq!(
            table_event("items_remove"),
            Some(("items", TableEvent::Remove))
        );
        assert_eq!(
            table_event("before_items_remove"),
            Some(("items", TableEvent::BeforeRemove))
        );
    }

    #[test]
    fn a_key_that_is_not_a_table_event_splits_into_nothing() {
        assert_eq!(table_event("refresh"), None);
        assert_eq!(table_event("status"), None);
        // A lifecycle name is not a table event even though it ends in a
        // suffix a fieldname could carry.
        assert_eq!(table_event("dirty"), None);
    }
}
